            /// </remarks>
            /// <seealso cref="ConjureActions.AddCallbacks(IConjureActions)" />
            /// <seealso cref="ConjureActions.RemoveCallbacks(IConjureActions)" />
            /// <seealso cref="ConjureActions.UnregisterCallbacks(IConjureActions)" />
